static inline int mapaCelda(int cx, int cy) {
    if (cx < 0 || cy < 0 || cx >= MAPA_CW || cy >= MAPA_CH) return 0;
    int i = cy * MAPA_CW + cx;
    return (MAPA_CELDA[i >> 2] >> ((i & 3) * 2)) & 3;
}

static inline int mapaEn(float x, float y) {
    return mapaCelda((int)(x / MAPA_CELL), (int)(y / MAPA_CELL));
}

static inline int mapaCaminable(float x, float y) { return mapaEn(x, y) != 0; }
static inline int mapaSalvaje(float x, float y)  { return mapaEn(x, y) == 2; }

